/// Pause following without moving the current viewport. An explicit disclosure
/// is reader navigation, not a new message or a request to jump to the end.
pub fn pause_following_tail(&mut self, cx: &mut Context<Self>) {
    self.list_state.pause_following_tail();
    cx.notify();
}

