/// An explicit disclosure is reader navigation. Keep its current anchor
/// through measurement; layout alone must not resume tail following.
/// Genuine scrolling to the bottom or Latest re-arms normal tail behavior.
pub fn hold_for_disclosure(&mut self, cx: &mut Context<Self>) {
    let anchor = self.list_state.logical_scroll_top();
    self.disclosure_hold = true;
    self.list_state.set_follow_mode(FollowMode::Normal);
    self.list_state.scroll_to(anchor);
    cx.notify();
}

// Only event-derived scroll callbacks call this, never measurement.
// Some offscreen rows may still have unknown heights: use the same
// measured-coordinate range as the scrollbar/user scroll clamp.
fn user_scrolled(&mut self, cx: &mut Context<Self>) {
    if self.disclosure_hold {
        let max = self.list_state.max_offset_for_scrollbar().y;
        let offset = -self.list_state.scroll_px_offset_for_scrollbar().y;
        if offset >= max - px(0.5) {
            self.disclosure_hold = false;
            self.list_state.set_follow_mode(FollowMode::Tail);
        }
    }
    cx.notify();
}

